/* GENERATED by scripts/sync-bichos.mjs from the avatar lab's styles/mascots.ts and styles/logos.ts: do not edit.
 * Only Sidevoice's own mascot ships (and the shade every figure uses). The lab's third-party mascots stay in the lab,
 * and nothing draws a mascot unless it is asked for by name: a conversation's seed always rolls a bicho. */

import { n } from "../core";

/** The mascots that ship. The lab calls a mascot's kind its harness. */
export const HARNESSES = ["sidevoice"] as const;
export type Harness = (typeof HARNESSES)[number];

const INK = "#1b1428";

/** The Sidevoice mark exactly as brand-resources/logo/mark/sidevoice-mark.svg draws it (24×24): five bars 3 wide with
 * fully rounded ends (rx 1.5), 1.5 apart, heights 6 : 12 : 21 : 12 : 6, all centred on y = 12. Bars are berenjena on
 * light grounds and lila on dark ones (sidevoice-mark-on-dark.svg); the fourth, "the other voice", is mustard in both. */
export const SIDEVOICE_24 = {
  rx: 1.5,
  /** x, y, width, height of each bar, left to right. */
  bars: [[1.5, 9, 3, 6], [6, 6, 3, 12], [10.5, 1.5, 3, 21], [15, 6, 3, 12], [19.5, 9, 3, 6]] as const,
  /** The bar that is always mustard (index into `bars`). */
  voiceBar: 3,
  berenjena: "#4a2f6b",
  lila: "#c9b6ec",
  mostaza: "#e0a82e",
};

/** A soft 3D shade for one colour: lit top-left, deep at the rim. Shapes use it by bounding box, so each piece is lit on its own.
 * `lift` (% white in the mid stop) and `rim` (% black at the edge) are for dark colours that would sink into the ink outline. */
export function shade(id: string, color: string, lift = 0, rim = 30) {
  const mid = lift ? `color-mix(in oklab, ${color}, white ${lift}%)` : color;
  return `<radialGradient id="${id}" cx=".36" cy=".3" r=".8"><stop offset="0" style="stop-color:color-mix(in oklab, ${color}, white 38%)"/><stop offset=".5" style="stop-color:${mid}"/><stop offset="1" style="stop-color:color-mix(in oklab, ${color}, black ${rim}%)"/></radialGradient>`;
}

export interface Mascot {
  defs: string;
  body: string;
  eyes: string;
  closed: string;
  mouthRest: string;
  mouthOpen: string;
  shine: string;
  traits: string;
  tone: string;
}

/** A mascot by name: only Sidevoice's. */
export function mascot(kind: Harness, id: string): Mascot {
  if (kind !== "sidevoice") throw new Error(`[bichos] no mascot "${String(kind)}" ships`);
  return sidevoice(id);
}

/** The Sidevoice mark as "la banda": the five bars of brand-resources' mark, placed with the same transform the other
 * logos use (translate(60 60) scale(4) translate(-12 -12)) but written out in the 120 box, so CSS lengths stay in avatar
 * units. Each bar is its own group (`pg-sv-1`…`pg-sv-5`) that bichos.ts scales from its own foot, so the rest frame is
 * the mark exactly. Bars 2 and 4 carry the eyes, the spine (bar 3) the mouth, and the mustard bar 4 is the agent.
 * The face lives outside the bars so it never stretches; `sv-ride` follows bar 4 when it perks up (listening) and
 * `sv-face` the idle slump. */
function sidevoice(id: string): Mascot {
  const { rx, bars, voiceBar, berenjena, mostaza } = SIDEVOICE_24;
  const at = (v: number) => n(12 + v * 4), len = (v: number) => n(v * 4);
  const body = bars.map(([x, y, w, h], i) => {
    const fill = i === voiceBar ? `url(#${id}m)` : `url(#${id}v)`;
    const gloss = i === 2 ? `<path class="shine" d="M${at(x) + 4} ${at(y) + 7} V${at(y) + 15}"/>` : "";
    return `<g class="pg-sv pg-sv-${i + 1}"><rect x="${at(x)}" y="${at(y)}" width="${len(w)}" height="${len(h)}" rx="${len(rx)}" fill="${fill}" stroke="${INK}" stroke-width="7" paint-order="stroke"/>${gloss}</g>`;
  }).join("");
  // Face details take each bar's own detail colour: crema on berenjena, noche on lila (both via --bx-sv-face), noche on mustard.
  const NOCHE = "#2a1a40", EY = 56, MY = 71;
  const eye = (x: number) => `<ellipse fill="#fff" stroke="${INK}" stroke-width="2.4" cx="${x}" cy="${EY}" rx="7" ry="8.5"/>`;
  const pupil = (x: number) => `<circle fill="${INK}" cx="${n(x + 0.5)}" cy="${EY + 1}" r="4.5"/><circle fill="#fff" cx="${n(x + 2)}" cy="${n(EY - 0.8)}" r="1.5"/>`;
  const shut = `M37 ${EY} Q42 ${EY + 4.6} 47 ${EY} M73 ${EY} Q78 ${EY + 4.6} 83 ${EY}`;
  const brow = (x: number, color: string, side: string) => `<path class="brow brow-${side}" fill="none" stroke="${color}" stroke-width="2.6" stroke-linecap="round" d="M${x - 4.5} 43.5 Q${x} 41.5 ${x + 4.5} 43.5"/>`;
  return {
    defs: shade(`${id}v`, "var(--bx-sv)", 12, 20) + shade(`${id}m`, mostaza),
    body: `${body}
      <g class="brows sv-brows">${brow(42, "var(--bx-sv-face)", "l")}<g class="sv-ride">${brow(78, NOCHE, "r")}</g></g>
      <path class="sweat prop-work" d="M25 25 Q30 32 25 35 Q20 32 25 25Z"/>`,
    eyes: `${eye(42)}<g class="look">${pupil(42)}</g><g class="sv-ride">${eye(78)}<g class="look">${pupil(78)}</g></g>`,
    closed: `<g class="sv-face"><path fill="none" stroke="${INK}" stroke-width="4.6" stroke-linecap="round" d="${shut}"/><path fill="none" stroke="#fff" stroke-width="1.7" stroke-linecap="round" d="${shut}"/></g>`,
    mouthRest: `<g class="sv-face"><path fill="none" stroke="var(--bx-sv-face)" stroke-width="2.4" stroke-linecap="round" d="M56 ${MY} Q60 ${MY + 4} 64 ${MY}"/></g>`,
    mouthOpen: `<path fill="${NOCHE}" stroke="var(--bx-sv-face)" stroke-width="1.6" stroke-linejoin="round" d="M55.6 ${MY - 1} H64.4 Q64.4 ${MY + 7} 60 ${MY + 7} Q55.6 ${MY + 7} 55.6 ${MY - 1}Z"/><ellipse fill="#ff6f91" cx="60" cy="${MY + 4.6}" rx="2.3" ry="1.4"/>`,
    shine: "",
    traits: "logo · Sidevoice",
    tone: berenjena,
  };
}
